import{_ as t,o as d,c as o,a2 as c}from"./chunks/framework.DGk0zlJw.js";const u=JSON.parse('{"title":"Beacon 重新设计计划（2026-10-16）· 现状核验表","description":"","frontmatter":{},"headers":[],"relativePath":"zh/design/redesign-2026-10-16-核验.md","filePath":"zh/design/redesign-2026-10-16-核验.md"}'),r={name:"zh/design/redesign-2026-10-16-核验.md"};function n(s,e,a,i,l,h){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="beacon-重新设计计划-2026-10-16-·-现状核验表" tabindex="-1">Beacon 重新设计计划（2026-10-16）· 现状核验表 <a class="header-anchor" href="#beacon-重新设计计划-2026-10-16-·-现状核验表" aria-label="Permalink to &quot;Beacon 重新设计计划（2026-10-16）· 现状核验表&quot;">​</a></h1><p><strong>核验对象</strong>：<code>docs/design/redesign-plan-2026-10-16.md</code>（外部设计稿，commit <code>f77b0d1</code>） <strong>核验日期</strong>：2026-10-16</p><blockquote><p><strong>性质声明</strong>：被核验的设计稿是<strong>外部建议，不是本仓事实</strong>。其中提到的「已有实现 / 此前设计」在核验前一律按<strong>未落文档</strong>处理，本表即动手前的核验记录。</p><p><strong>「查无」的含义</strong>：只说明本仓代码与文档里<strong>从未写下来</strong>，<strong>不能证明从未设计过</strong>。凡标「查无」的条目，若后续找到设计出处，应回填本表，而不是当作全新需求重复立项。</p></blockquote><hr><h2 id="一、核验口径" tabindex="-1">一、核验口径 <a class="header-anchor" href="#一、核验口径" aria-label="Permalink to &quot;一、核验口径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分类</th><th>含义</th><th>记法</th></tr></thead><tbody><tr><td><strong>已实现</strong></td><td>代码存在，且仓内文档已有记载</td><td>给 <code>file:line</code> + 文档出处</td></tr><tr><td><strong>部分已实现</strong></td><td>断言可拆分，逐项标注</td><td>已实现的部分给 <code>file:line</code>，未实现的部分写查无</td></tr><tr><td><strong>未落文档但确有其事</strong></td><td>代码存在，仓内文档从未记载（含文档只写验收口径、不写机制的情形）</td><td>给 <code>file:line</code> 并标注需补记</td></tr><tr><td><strong>查无</strong></td><td>代码与文档均无</td><td>写「查无」；若仓内有反向记录或暂缓记录，附出处与设计稿原文</td></tr></tbody></table><p>「已实现（部分）」的条目一律逐项拆写，不用「大致符合」这类模糊结论。</p><hr><h2 id="二、逐条核验" tabindex="-1">二、逐条核验 <a class="header-anchor" href="#二、逐条核验" aria-label="Permalink to &quot;二、逐条核验&quot;">​</a></h2><h3 id="a-产品定位与总体架构" tabindex="-1">A. 产品定位与总体架构 <a class="header-anchor" href="#a-产品定位与总体架构" aria-label="Permalink to &quot;A. 产品定位与总体架构&quot;">​</a></h3><table tabindex="0"><thead><tr><th>编号</th><th>设计稿断言</th><th>分类</th><th>依据</th></tr></thead><tbody><tr><td>A01</td><td>单进程模块化应用；<code>Beacon.App</code> / <code>Beacon.Core</code> / <code>Beacon.Connections</code> / <code>Beacon.Actions</code> / <code>Beacon.Storage</code> 五个项目</td><td>已实现</td><td><code>src/</code> 五个 csproj + <code>Beacon.sln</code>；文档 <code>docs/solution-structure.md:10-23</code></td></tr><tr><td>A02</td><td>依赖规则：Core 不依赖 WinUI / WebView2 / 具体 Provider；Connections、Actions、Storage 只依赖 Core；App 是依赖注入与运行时组装入口</td><td>已实现</td><td><code>src/Beacon.Core/Beacon.Core.csproj:6-8</code> 仅引 <code>Microsoft.Extensions.Logging.Abstractions</code>；<code>Beacon.Connections.csproj:7</code> / <code>Beacon.Actions.csproj:7</code> / <code>Beacon.Storage.csproj:7</code> 各只引 Core；<code>src/Beacon.App/App.xaml.cs:474</code> <code>BuildServices</code> + <code>:147</code> <code>BeaconRuntime.Start</code>。<strong>文档偏差</strong>：<code>docs/solution-structure.md:45</code> 写「把 Provider/Executor/Store 注册进 DI」，实际 Provider/Executor/Store 是 <code>BeaconRuntime.Start</code> 内手动 <code>new</code>，进 DI 的只有壳服务</td></tr><tr><td>A03</td><td>显示组件只消费状态，不直接访问 Provider 或凭据；UI 只消费状态、不直接拉数据</td><td>已实现</td><td>事件流 <code>docs/rfc/RFC-001-technical-design.md:42,54-63</code>（单向数据流）；凭据只经 <code>ConnectionContext.Secrets</code> 注入 Provider（<code>src/Beacon.Core/Services/WidgetHost.cs:131</code>）；UI 侧经 <code>IWidgetProvider</code> 抽象取状态（<code>src/Beacon.App/Windows/FloatingTileWindow.cs:55</code>）</td></tr><tr><td>A04</td><td>现有代码已具备六件：Provider、状态缓存、事件总线、刷新调度、Action 执行器、桌面 Widget 基础</td><td>已实现</td><td>Provider 注册表 <code>src/Beacon.App/Services/BeaconRuntime.cs:116-141</code>（23 个 widget provider）+ <code>:183</code> 起（17 个 connection provider）；缓存 <code>src/Beacon.Core/Abstractions/ICacheStore.cs:6</code>；事件总线 <code>src/Beacon.Core/Abstractions/IEventBus.cs:4</code>；调度 <code>src/Beacon.Core/Services/RefreshScheduler.cs:17</code>；执行 <code>src/Beacon.Core/Services/ActionRunner.cs:15</code> + 7 个 <code>IActionExecutor</code>（<code>src/Beacon.Actions/*.cs</code> + <code>src/Beacon.Connections/GitHubWorkflowExecutors.cs:70,98,121</code>）；窗口 <code>src/Beacon.App/Windows/</code>（Capsule / PinnedHost / FloatingTile / QuickPanel / Detail / Settings）+ <code>Services/TrayIconService.cs</code></td></tr><tr><td>A05</td><td>数据单向流：RefreshScheduler → Provider 拉取 → WidgetState → Event Bus → 聚合 / 通知 / UI</td><td>已实现</td><td><code>docs/rfc/RFC-001-technical-design.md:54-63</code>；代码 <code>src/Beacon.Core/Services/StatusAggregator.cs:29-36</code>（聚合）、<code>src/Beacon.Core/Services/NotificationEngine.cs:14</code>（通知）、<code>src/Beacon.App/Windows/QuickPanelWindow.cs:231-246</code>（UI）</td></tr><tr><td>A06</td><td>不新增后台服务、独立数据库或云端服务</td><td>已实现</td><td>全仓无数据库依赖、无监听端口服务；唯一 HTTP 出站 = <code>src/Beacon.App/Services/UpdateCheckService.cs:24</code>（GitHub <code>releases/latest</code> 只读检查）</td></tr></tbody></table><h3 id="b-数据获取与响应式状态" tabindex="-1">B. 数据获取与响应式状态 <a class="header-anchor" href="#b-数据获取与响应式状态" aria-label="Permalink to &quot;B. 数据获取与响应式状态&quot;">​</a></h3><table tabindex="0"><thead><tr><th>编号</th><th>设计稿断言</th><th>分类</th><th>依据</th></tr></thead><tbody><tr><td>B01</td><td>Provider 连接外部系统（GitHub / Jenkins / HTTP / AI Usage / 本地数据源）</td><td>已实现</td><td>23 个 widget provider 注册于 <code>src/Beacon.App/Services/BeaconRuntime.cs:115-139</code>；17 类连接见 <code>docs/solution-structure.md:21</code></td></tr><tr><td>B02</td><td>Provider 不负责绘制 UI、不直接调用显示组件、也不决定通知是否弹出</td><td>已实现</td><td><code>src/Beacon.Connections/Beacon.Connections.csproj:7</code> 仅引 Core（无任何 UI 引用）；通知由 <code>NotificationEngine</code> 依规则判定（<code>src/Beacon.Core/Services/NotificationEngine.cs:14</code>），Provider 只发事件</td></tr><tr><td>B03</td><td>标准化数据保留来源标识、更新时间、数据新鲜度和外部详情链接</td><td>已实现</td><td><code>src/Beacon.Core/Models/WidgetState.cs:8</code>（ConnectionId）、<code>:18</code>（FetchedAt）、<code>:20</code>（IsStale）、<code>:12</code>（DetailUrl）</td></tr><tr><td>B04</td><td>刷新调度、认证、超时、重试、限流和缓存属于数据获取层</td><td>部分已实现</td><td>已实现：分档调度 <code>src/Beacon.Core/Services/RefreshScheduler.cs:6-10</code>（Tier + IntervalOverride）、失败退避 <code>:241</code> <code>NextDelay</code>、缓存 <code>src/Beacon.Storage/JsonCacheStore.cs:11-17,76</code>。查无：<strong>限流</strong>无独立限流组件（限流语义由各 Provider 自行实现，无统一层）；<strong>认证</strong>无统一认证层，凭据经 <code>ISecretStore</code> 注入（<code>src/Beacon.Core/Abstractions/ISecretStore.cs:5</code>）</td></tr><tr><td>B05</td><td>外部状态映射到 Beacon 领域模型（Jenkins SUCCESS → <code>LifecycleState.Success</code> 等）</td><td>已实现</td><td><code>src/Beacon.Core/Models/WidgetState.cs:15</code>（Lifecycle）；映射实现见 <code>src/Beacon.Connections/JenkinsBuildProvider.cs</code>、<code>src/Beacon.Connections/GitHubActionsProvider.cs</code></td></tr><tr><td>B06</td><td>建立统一的运行时状态入口，建议命名为 <code>IStateStore</code></td><td>查无</td><td>全仓无 <code>IStateStore</code> 类型与 <code>StateStore</code> 实现（grep 零命中）。当前状态分布：<code>WidgetHost</code> 内存 + <code>StatusAggregator</code> 快照（<code>src/Beacon.Core/Services/StatusAggregator.cs:17-19</code>）+ <code>ICacheStore</code> 持久化（<code>src/Beacon.Core/Abstractions/ICacheStore.cs:6</code>）</td></tr><tr><td>B07</td><td>Selector：从状态中提取显示组件所需信息的纯函数，同一份状态可存在多个 Selector</td><td>查无</td><td>全仓无 Selector 抽象（grep 零命中）。功能最近的等价物是静态推导 <code>src/Beacon.Core/Services/WidgetValueHint.cs:12</code> 与 <code>src/Beacon.Core/Services/QuickPanelFilter.cs:8</code>，均为静态类、非可组合选择器</td></tr><tr><td>B08</td><td>派生状态五项：额度百分比 / 需关注事项数 / 是否存在失败任务 / 多任务最严重状态 / 任务耗时是否超阈值</td><td>部分已实现</td><td>已实现 4 项：额度百分比 <code>src/Beacon.Connections/BigModelUsageProvider.cs:124</code>（<code>QuotaWindows.Select</code>，<code>:88</code>）、需关注数 <code>src/Beacon.Core/Services/StatusAggregator.cs:86</code>（Compute 内分级计数）、失败存在性 <code>WidgetState.cs:9</code>（Severity）、最严重状态 <code>StatusAggregator.cs:9</code>（Overall = max severity）。查无 1 项：<strong>任务耗时阈值判定</strong>全仓无 duration 字段与阈值逻辑</td></tr><tr><td>B09</td><td>状态相同的轮询结果不导致所有组件重绘；刷新时间变化与业务内容变化要区分</td><td>查无</td><td>现状与设计稿诉求相反：<code>WidgetHost</code> 成功路径<strong>逐跳无条件发布</strong>（<code>src/Beacon.Core/Services/WidgetHost.cs:138</code>），UI 逐跳重建（<code>src/Beacon.App/Windows/QuickPanelWindow.cs:242-245</code>）；「内容无新值不重发」由 Provider 契约承担——返回 <code>null</code> 即不重发不写缓存（<code>WidgetHost.cs:124-128</code>），由各 Provider 自行以 ETag/缓存判定（ETag 见 <code>src/Beacon.Connections/GitHubApiClient.cs</code>）。<strong>反向证据</strong>：<code>WidgetState</code> 的内容相等比较<strong>包含 FetchedAt</strong>（<code>src/Beacon.Core/Models/WidgetState.cs:36</code>），即每次刷新都判为状态变化，无法用于去重</td></tr><tr><td>B10</td><td>变更检测；避免多个刷新请求同时覆盖更新后的状态</td><td>部分已实现</td><td>已实现：同 <code>(ConnectionId, Tier, IntervalOverride)</code> 组内串行（<code>RefreshScheduler.cs:32-33</code> + <code>:185</code>），组内不并发覆盖。查无：<strong>状态版本号/逻辑时钟</strong>不存在，覆盖防护只到「同组串行」这一层</td></tr><tr><td>B11</td><td>State / Event / Command / Operation / Operation Result / Preference 六类概念</td><td>部分已实现</td><td>已实现：State=<code>WidgetState.cs:4</code>、Event=<code>src/Beacon.Core/Events/Events.cs:6-22</code>（5 个记录）、Command=<code>src/Beacon.Core/Models/ActionModels.cs:6-15</code>、Operation Result=<code>ActionModels.cs:28</code>。查无：<strong>Command 与 Operation 无显式类型命名</strong>（只有 <code>ActionConfig</code> 与 <code>ActionResult</code>，无 Operation 过程类型）；<strong>Preference 无统一类型</strong>（已读 = <code>src/Beacon.Core/Models/NotificationModels.cs:74</code> <code>Read</code>，固定/静默/显示模式散落在 <code>AppConfig</code> 各属性，如 <code>src/Beacon.Core/Models/AppConfig.cs:25</code>）</td></tr><tr><td>B12</td><td>UI 线程不被后台网络请求阻塞</td><td>已实现</td><td><code>src/Beacon.Core/Abstractions/IEventBus.cs:12-22</code>（<code>IUiDispatcher</code> + <code>SubscribeOnUi</code> marshal）；<code>src/Beacon.Core/Services/DispatchGuard.cs:14</code> 兜底 UI 派发异常</td></tr></tbody></table><h3 id="c-显示系统" tabindex="-1">C. 显示系统 <a class="header-anchor" href="#c-显示系统" aria-label="Permalink to &quot;C. 显示系统&quot;">​</a></h3><table tabindex="0"><thead><tr><th>编号</th><th>设计稿断言</th><th>分类</th><th>依据</th></tr></thead><tbody><tr><td>C01</td><td>组件分为数据组件 / 显示组件 / 交互组件三类，可组合但不可相互绑定</td><td>查无</td><td>全仓无组件分类抽象。现状是一套通用行渲染 <code>src/Beacon.App/Windows/QuickPanelWindow.cs:471</code> <code>MakeStateRow</code>（看板状态行与事件行同构）+ 各 WidgetType 的 payload 展示</td></tr><tr><td>C02</td><td>第一批标准显示组件目录：A 状态与指标 9 项 / B 任务与信息列表 12 项 / C 数据可视化 8 项 / D 布局与组合 12 项 / E 交互组件 10 项</td><td>查无</td><td>上述 51 项组件在仓内<strong>均无对应实现</strong>（<code>Metric</code> / <code>Status Badge</code> / <code>Progress Ring</code> / <code>Gauge</code> / <code>Countdown</code> / <code>Comparison</code> / <code>Task List</code> / <code>Event Timeline</code> / <code>Activity Feed</code> / <code>Data Table</code> / <code>Ranked List</code> / <code>Queue View</code> / <code>Error Summary</code> / <code>Empty State</code> / <code>Sparkline</code> / <code>Line Chart</code> / <code>Bar Chart</code> / <code>Donut Chart</code> / <code>Heatmap</code> / <code>Split View</code> / <code>Tabs</code> / <code>Conditional</code> / <code>Repeat</code> / <code>HTML Screen</code> / <code>Icon Button</code> / <code>Toggle</code> / <code>Acknowledge</code> / <code>Retry</code> / <code>Confirm Dialog</code> / <code>Tooltip</code> / <code>Expand / Collapse</code> —— grep 全部零命中）</td></tr><tr><td>C03</td><td>组件分层：Primitives / Data / Layout / Interaction / Composite</td><td>查无</td><td>无分层目录与分层契约（<code>docs/solution-structure.md:98</code> 记 Connections 为「文件平铺无子目录」）</td></tr><tr><td>C04</td><td>同一份数据可被多个组件展示；一个显示实例可绑定多个数据源</td><td>部分已实现</td><td>已实现：单份 <code>WidgetState</code> 同时进胶囊 / 托盘 / L0 状态灯 / L2 面板 / L3（<code>StatusAggregator.cs:29-36</code> + <code>WidgetHost.cs:138</code> 单一事件源）。查无：<strong>一实例绑多数据源</strong>——<code>WidgetState.cs:8</code> 单 <code>ConnectionId</code>，一个 Widget 实例只对一个连接</td></tr><tr><td>C05</td><td>布局变化只更新布局不重新获取业务数据；主题变化不触发网络请求</td><td>部分已实现</td><td>已实现：主题变化走本地换色（<code>src/Beacon.App/Services/UiPalette.cs:1</code>、<code>src/Beacon.App/Windows/ThemeColors.cs:1</code>、<code>src/Beacon.App/Services/MotionEngine.cs:1</code>），刷新只由定时或 Action kick 驱动（<code>RefreshScheduler.cs:227</code> <code>Kick</code>）。查无：<strong>布局与刷新的显式隔离类型</strong>不存在，只有「刷新不经 UI」这一事实</td></tr><tr><td>C06</td><td>组件是否允许固定到桌面需有明确标记</td><td>已实现</td><td><code>src/Beacon.Core/Models/WidgetTypeDescriptor.cs:20</code> <code>PinSupported</code>、<code>:25</code> <code>FloatingSupported</code>、<code>:28</code> <code>FloatingOptIn</code>；准入判定 <code>src/Beacon.App/Windows/QuickPanelWindow.cs:534</code>、<code>FloatingTileWindow.cs:55-64</code>、<code>PinnedHostWindow.cs:672</code></td></tr><tr><td>C07</td><td>Composite Component 由基础组件组合，不重新实现数据获取或 Action 调用</td><td>查无</td><td>无 Composite 组件层；现有组合发生在 XAML/code-behind 内（各 Window 直接读 <code>WidgetState</code>）</td></tr></tbody></table><h3 id="d-统一视觉设计系统" tabindex="-1">D. 统一视觉设计系统 <a class="header-anchor" href="#d-统一视觉设计系统" aria-label="Permalink to &quot;D. 统一视觉设计系统&quot;">​</a></h3><table tabindex="0"><thead><tr><th>编号</th><th>设计稿断言</th><th>分类</th><th>依据</th></tr></thead><tbody><tr><td>D01</td><td>设计令牌至少含：色彩、字体、间距、圆角、阴影、动效、尺寸密度、状态</td><td>查无</td><td><strong>文档层面查无「设计令牌」概念</strong>（<code>设计令牌</code> / <code>Design System</code> / <code>Design token</code> 在 docs 内零命中）。代码层只有零散常量类：色彩 <code>src/Beacon.App/Services/UiPalette.cs:1</code>、动效 <code>src/Beacon.App/Services/MotionEngine.cs:1</code>、尺寸换算 <code>src/Beacon.Core/Services/DpiLayoutMath.cs:10</code>；<strong>字体、间距、圆角、阴影无令牌体系</strong>（硬编码在各窗口 XAML）</td></tr><tr><td>D02</td><td>三种视觉密度：Compact / Comfortable / Detailed，同一组件适配三种场景</td><td>查无</td><td>三种密度在代码与文档中均无（<code>Density</code> 零命中）。<strong>相关概念已落文档</strong>：信息密度门槛见 <code>docs/master-plan.md:327</code>、<code>docs/mission-excerpt.md:338</code>，但那是「悬浮窗准入的信息密度门槛」，与设计稿的「三档密度适配」不是一回事</td></tr><tr><td>D03</td><td>状态不只通过颜色区分，还应通过图标、文字或辅助信息表达</td><td>已实现</td><td>tile / 胶囊 / 面板均带文本与计数：<code>src/Beacon.App/Windows/QuickPanelWindow.cs:471</code> <code>MakeStateRow</code>（Summary + 时间 + tag）、<code>src/Beacon.App/Windows/PinnedHostWindow.cs:313,326</code>（Last update 文本）、胶囊 <code>CapsuleWindow.cs</code></td></tr><tr><td>D04</td><td>每个组件必须明确：默认尺寸与最小尺寸、加载/正常/空/错误/离线/过期状态、悬停/按下/焦点/禁用、可访问性名称与键盘操作、是否允许固定、小尺寸降级</td><td>部分已实现</td><td>已实现：固定准入（C06）、离线/过期态（<code>WidgetState.cs:20-21</code> IsStale / ConnectionHealthy，<code>PinnedHostWindow.cs:313-326</code> 灰显 + Last update）、UIA 名称（<code>PinnedHostWindow</code> / <code>QuickPanelWindow</code> 均带 AutomationId/Name，CI 场景 N/S/X 用 UIA 命中）。查无：<strong>统一的组件级规格</strong>（无 default size / min size / hover-pressed-focus-disabled 的统一约定，也无小尺寸降级规则表）；<strong>键盘操作</strong>仅 Esc 关闭（<code>src/Beacon.App/App.xaml.cs:295</code> 附近）与系统 Tab，无键盘导航规范</td></tr><tr><td>D05</td><td>为组件库建立独立的视觉示例页</td><td>查无</td><td>全仓无示例页 / Gallery 窗口（<code>src/Beacon.App/Windows/</code> 七个窗口全是产品窗口）</td></tr></tbody></table><h3 id="e-html-小屏幕架构" tabindex="-1">E. HTML 小屏幕架构 <a class="header-anchor" href="#e-html-小屏幕架构" aria-label="Permalink to &quot;E. HTML 小屏幕架构&quot;">​</a></h3><table tabindex="0"><thead><tr><th>编号</th><th>设计稿断言</th><th>分类</th><th>依据</th></tr></thead><tbody><tr><td>E01</td><td>HTML 小屏幕由 Template / DataBindings / ActionBindings / Theme / Layout / RefreshPolicy / RuntimeState 组成</td><td>查无</td><td>无 HTML 渲染、无模板加载、无绑定层（<code>WebView2</code> / <code>HtmlScreen</code> / <code>DataBindings</code> 全部零命中）。<strong>仓内已有反向记录</strong>：<code>docs/master-plan.md:769</code>「悬浮窗口应尽可能使用原生 Windows 能力实现，不引入 WebView 或其他 UI 框架来重复实现桌面外壳」；<code>docs/mission-excerpt.md:435</code> 在「跨平台桌面应用的代价」清单中明确排除 WebView</td></tr><tr><td>E02</td><td>原生组件与 HTML 组件共享状态读取接口、数据绑定语义、Action ID 与参数约定、主题令牌、尺寸与生命周期、错误状态与更新时间</td><td>查无</td><td>HTML 面不存在，契约无从共享</td></tr><tr><td>E03</td><td>HTML 安全边界七条（页面不得取凭据 / Action 只经受控桥接 / 不得执行任意本地命令 / 外部导航与网络受控 / 模板限制本地文件与脚本 / 命令参数在 Core 校验 / 错误模板不崩溃）</td><td>查无</td><td>无 HTML 桥接实现；其中「错误不导致崩溃」原则的落点是 <code>src/Beacon.Core/Services/DispatchGuard.cs:14</code>（UI 派发异常兜底），与安全边界清单无关</td></tr></tbody></table><h3 id="f-action-与反馈架构" tabindex="-1">F. Action 与反馈架构 <a class="header-anchor" href="#f-action-与反馈架构" aria-label="Permalink to &quot;F. Action 与反馈架构&quot;">​</a></h3><table tabindex="0"><thead><tr><th>编号</th><th>设计稿断言</th><th>分类</th><th>依据</th></tr></thead><tbody><tr><td>F01</td><td>Action 具有稳定标识、参数契约和明确的执行结果</td><td>已实现</td><td><code>src/Beacon.Core/Models/ActionModels.cs:8</code> <code>Id</code>、<code>:10</code> <code>Type</code>（<code>&quot;open.url&quot;</code> / <code>&quot;http&quot;</code> / <code>&quot;gh.workflow_dispatch&quot;</code> / <code>&quot;local.command&quot;</code> / <code>&quot;webhook&quot;</code>）、<code>:14</code> <code>Parameters</code>；结果 <code>ActionModels.cs:28</code> <code>ActionResult</code></td></tr><tr><td>F02</td><td>执行结果至少支持 Succeeded / Failed / Cancelled / TimedOut / Unsupported；异步外部任务还需区分「请求已接受」与「外部任务最终完成」</td><td>查无</td><td>现有 <code>ActionResult</code> 只有 <code>bool Success</code> + <code>string? Message</code>（<code>ActionModels.cs:28-33</code>），<strong>无五态枚举、无区分</strong>。异步任务的完成态靠轮询跟踪：<code>src/Beacon.Connections/GitHubWorkflowExecutors.cs:79-80</code>（workflow 级 10s 常规轮询至终态），结果语义即「已触发 / 已重跑 / 已请求取消」</td></tr><tr><td>F03</td><td>继续复用现有 Action Runner 和 Executor，不额外建立并行执行框架</td><td>已实现</td><td>单一执行路径 <code>src/Beacon.Core/Services/ActionRunner.cs:15</code>；7 个执行器（<code>src/Beacon.Actions/HttpExecutor.cs:12</code>、<code>LocalCommandExecutor.cs:11</code>、<code>OpenUrlExecutor.cs:13</code>、<code>WebhookExecutor.cs:16</code>、<code>GitHubWorkflowExecutors.cs:70,98,121</code>）；路由/确认/超时单测 <code>docs/solution-structure.md</code>（ActionRunnerTests 9 例）</td></tr><tr><td>F04</td><td>用户偏好（已读、已确认、静默、固定组件、显示模式）作为独立本地状态，不改写外部系统真实状态</td><td>已实现</td><td>已读 <code>src/Beacon.Core/Models/NotificationModels.cs:74</code> <code>Read</code>；固定 / 显示模式 / 动效档位均为 <code>AppConfig</code> 本地项（<code>src/Beacon.Core/Models/AppConfig.cs:25</code> 等）；执行器只调外部 API 不改本地业务状态（<code>src/Beacon.Connections/GitHubWorkflowExecutors.cs:98-113</code> rerun 只发 POST）</td></tr></tbody></table><h3 id="g-配置与持久化" tabindex="-1">G. 配置与持久化 <a class="header-anchor" href="#g-配置与持久化" aria-label="Permalink to &quot;G. 配置与持久化&quot;">​</a></h3><table tabindex="0"><thead><tr><th>编号</th><th>设计稿断言</th><th>分类</th><th>依据</th></tr></thead><tbody><tr><td>G01</td><td>继续使用本地 JSON 配置：<code>config.json</code>（全局/主题/热键/密度/通知策略）、<code>connections.json</code>、<code>widgets.json</code>、<code>pins.json</code>、<code>actions.json</code>、<code>notifications.json</code>、<code>cache/</code>、<code>secrets.bin</code></td><td>已实现</td><td>八个文件名在代码中全部命中（<code>grep</code> 实证：<code>config.json</code> 4 处、<code>connections.json</code> / <code>widgets.json</code> / <code>pins.json</code> / <code>actions.json</code> / <code>notifications.json</code> 各 2 处、<code>secrets.bin</code> 1 处）；<code>cache/</code> = <code>src/Beacon.Storage/JsonCacheStore.cs:76</code> <code>states.json</code>；文档 <code>docs/configuration.md</code></td></tr><tr><td>G02</td><td>不为新架构重命名或迁移全部配置文件</td><td>已实现</td><td>沿用现有文件名，无迁移代码</td></tr><tr><td>G03</td><td>敏感凭据由安全存储管理，配置 JSON 只存引用不落明文</td><td>已实现</td><td><code>src/Beacon.Storage/DpapiSecretStore.cs:19-22</code>（DPAPI CurrentUser，<code>secrets.bin</code>）；引用接口 <code>src/Beacon.Core/Abstractions/ISecretStore.cs:7-11</code>（credentialRef）；<code>docs/rfc/RFC-001-technical-design.md:26</code>（Local First / Secrets 进系统安全存储）</td></tr></tbody></table><h3 id="h-项目模块划分与边界" tabindex="-1">H. 项目模块划分与边界 <a class="header-anchor" href="#h-项目模块划分与边界" aria-label="Permalink to &quot;H. 项目模块划分与边界&quot;">​</a></h3><table tabindex="0"><thead><tr><th>编号</th><th>设计稿断言</th><th>分类</th><th>依据</th></tr></thead><tbody><tr><td>H01</td><td><code>Beacon.Core</code> 内含 State Store、State Transitions、Selectors、Event Bus、Refresh Scheduler、Notification Engine、Action Dispatcher / Runner、Component Contracts、Binding Engine、Layout / Theme Contracts</td><td>查无</td><td>已实现 4 项：Event Bus <code>IEventBus.cs:4</code>、Refresh Scheduler <code>RefreshScheduler.cs:17</code>、Notification Engine <code>NotificationEngine.cs:14</code>、Action Dispatcher / Runner <code>ActionRunner.cs:15</code>。<strong>查无 6 项</strong>：State Store（B06）、State Transitions（无转移类型）、Selectors（B07）、Component Contracts、Binding Engine、Layout / Theme Contracts 均无对应类型</td></tr><tr><td>H02</td><td><code>Beacon.App</code> 内含 Windows Shell、Tray / Hotkey、Window Host、Quick Panel / Detail / Settings、Native Renderer、HTML Renderer Host、UI Composition Root</td><td>部分已实现</td><td>已实现：Windows Shell（<code>Services/</code>）、Tray <code>Services/TrayIconService.cs</code>、Hotkey <code>Services/HotkeyService.cs</code>、Window Host <code>Windows/PinnedHostWindow.cs</code>、Quick Panel / Detail / Settings（<code>Windows/</code>）、UI Composition Root ≈ <code>Services/BeaconRuntime.cs:104</code> <code>Start</code>。查无：<strong>Native Renderer 与 HTML Renderer Host 无对应抽象</strong>（渲染即各 Window 的 XAML + code-behind）</td></tr><tr><td>H03</td><td>「明确不做」：Workflow Engine、任意脚本执行平台、远程机器与服务器管理、云端账号/团队协作/多设备、第三方插件市场、不要求所有组件用 HTML、不要求 React、完整事件溯源、不为每种外部数据源复制 UI、不为展示引入复杂图表动画</td><td>已落文档（代码层面查无）</td><td><code>docs/rfc/RFC-001-technical-design.md:31</code>（非目标清单）、<code>docs/master-plan.md:125-134</code>（不做：Docker/服务器/远程机器管理、AI Agent 管理、多设备控制或云同步、第三方插件市场、复杂图表和分析报表、通用监控平台、账号注册/团队协作/独立后端）、<code>docs/mission-excerpt.md:1425-1432</code>。<strong>注意与设计稿的差异</strong>：设计稿未列「复杂图表 / 复杂主题 / 数据库 / 云账号 / 用户系统 / 团队协作 / 云同步 / Jenkins·Docker 全功能管理 / AI Agent 管理」，设计稿的「不做」清单是本仓既有清单的<strong>真子集加 React 一条</strong>，不构成新边界</td></tr><tr><td>H04</td><td>现有代码应优先映射到新职责、能复用的直接复用；不要直接重写整套 Core</td><td>判断性结论（现状支持）</td><td>本仓现状：Provider / 事件总线 / 调度 / 执行器 / 存储五件均已在位并可映射（A04）；<code>docs/solution-structure.md:43</code> 已立「Core 不引用任何项目」的可替换约束</td></tr></tbody></table><h3 id="i-设计稿相邻能力的仓内落点-对照用" tabindex="-1">I. 设计稿相邻能力的仓内落点（对照用） <a class="header-anchor" href="#i-设计稿相邻能力的仓内落点-对照用" aria-label="Permalink to &quot;I. 设计稿相邻能力的仓内落点（对照用）&quot;">​</a></h3><blockquote><p>本节不是设计稿的「现状断言」，而是核验过程中顺带发现的能力。其中 <strong>I01 I02 I03 I05</strong> 代码存在而文档零记载，属「未落文档但确有其事」，<strong>需补记而非新建</strong>；I04 / I06 文档已有记载，列出供对照「设计稿的组件/动作契约在仓内目前的落点是什么」。</p></blockquote><table tabindex="0"><thead><tr><th>编号</th><th>能力</th><th>分类</th><th>依据</th></tr></thead><tbody><tr><td>I01</td><td>动效三档 <code>MotionMode { Off, Reduced, Full }</code> + <code>MotionEngine</code>（含呼吸、脉冲、变色过渡；reduced 档不启动呼吸）</td><td>未落文档但确有其事</td><td><code>src/Beacon.App/Services/MotionEngine.cs:12-17</code>；仓内文档只有验收口径（<code>docs/mvp-issues.md</code>、<code>docs/acceptance-*.md</code>），机制层零记载</td></tr><tr><td>I02</td><td>UI 派发异常兜底 <code>DispatchGuard.Wrap</code> + <code>DispatcherQueueGuard.EnqueueGuarded</code>（WinUI 3 <code>DispatcherQueue</code> 无 <code>HandlerException</code>、<code>TryEnqueue</code> 回调异常不经 <code>UnhandledException</code> 路由）</td><td>未落文档但确有其事</td><td><code>src/Beacon.Core/Services/DispatchGuard.cs:14</code>、<code>src/Beacon.App/Services/DispatcherQueueGuard.cs:17,31</code>；<code>docs/</code> 内 grep <code>DispatchGuard</code> 零命中</td></tr><tr><td>I03</td><td>UI 文案本地化唯一机制 <code>UiStrings</code>（en/zh 双字典、空串跟随系统、<code>LanguageChanged</code> 广播、设置语言即时生效）</td><td>未落文档但确有其事</td><td><code>src/Beacon.Core/Services/UiStrings.cs:12,64-82,100</code>；<code>docs/configuration.md</code> 未记载该机制与 <code>settings.language</code> 字段</td></tr><tr><td>I04</td><td>声明式 Provider DSL <code>ProviderDsl</code>（HTTP 等以代码声明字段与动作，执行走既有 <code>TemplateRenderer</code>）</td><td>已实现（有文档）</td><td><code>src/Beacon.Connections/ProviderDsl.cs:15</code>；文档 <code>docs/mvp-issues.md</code>、<code>docs/solution-structure.md</code>、<code>docs/acceptance-checklist.md</code></td></tr><tr><td>I05</td><td>看板事件过滤 <code>QuickPanelFilter</code>（默认全部 + 点击 chip 过滤 + 活动 chip 高亮 + 概览头显示当前源）</td><td>未落文档但确有其事</td><td><code>src/Beacon.Core/Services/QuickPanelFilter.cs:8</code>；实现见 <code>src/Beacon.App/Windows/QuickPanelWindow.cs</code>；<code>docs/configuration.md</code> 未记载</td></tr><tr><td>I06</td><td>悬浮窗准入与数值类悬浮开关 <code>WidgetDisplayPolicy</code>（PinEntryVisible / IsNumericSuppressed / PanelCarries）</td><td>部分未落文档</td><td><code>src/Beacon.Core/Models/WidgetDisplayPolicy.cs:9,11,17,22</code>；<code>docs/configuration.md</code> 只记 <code>numericFloatingEnabled</code> 字段，准入判定链未记载</td></tr></tbody></table><hr><h2 id="三、统计" tabindex="-1">三、统计 <a class="header-anchor" href="#三、统计" aria-label="Permalink to &quot;三、统计&quot;">​</a></h2><p><strong>核验条目总数：50</strong>（A 组 6 条 + B 组 12 条 + C 组 7 条 + D 组 5 条 + E 组 3 条 + F 组 4 条 + G 组 3 条 + H 组 4 条 + I 组 6 条）</p><table tabindex="0"><thead><tr><th>分类</th><th>条数</th><th>编号</th></tr></thead><tbody><tr><td>已实现</td><td>20</td><td>A01 A02 A03 A04 A05 A06 / B01 B02 B03 B05 B12 / C06 / D03 / F01 F03 F04 / G01 G02 G03 / I04</td></tr><tr><td>部分已实现</td><td>9</td><td>B04 B08 B10 B11 / C04 C05 / D04 / H02 / I06</td></tr><tr><td>查无</td><td>15</td><td>B06 B07 B09 / C01 C02 C03 C07 / D01 D02 D05 / E01 E02 E03 / F02 / H01</td></tr><tr><td>未落文档但确有其事</td><td>4</td><td>I01 I02 I03 I05</td></tr><tr><td>已落文档（代码查无，属边界声明）</td><td>1</td><td>H03</td></tr><tr><td>判断性结论（现状支持，非实现断言）</td><td>1</td><td>H04</td></tr></tbody></table><blockquote><p>注 1：B09 标「查无」是指<strong>设计稿的诉求在仓内无对应实现</strong>（无去重、无刷新时间与内容区分），不是指 Provider 的「内容无新值不重发」契约不存在——后者与串行调度防护在 B04 / B10 的「部分已实现」里已逐项记明。 注 2：分类条数合计 50，与条目总数一致。</p></blockquote><p><strong>分布小结</strong>：设计稿中关于「已有实现」的断言，<strong>约六成在仓内确有其事</strong>（20 条已实现 + 4 条未落文档但确有其事 + 1 条部分未落文档）；「响应式状态系统」与「显示组件库」两章的基本前提在仓内<strong>大面积查无</strong>（B06 B07 / C01 C02 C03 / D01 D02 / H01 共 9 条），这两章应视为<strong>目标设计</strong>而非现状描述；HTML 小屏幕一章（E 组 3 条）查无，且仓内已有反向记录（<code>docs/master-plan.md:769</code>），<strong>不得当作全新需求立项</strong>。</p>',34)])])}const p=t(r,[["render",n]]);export{u as __pageData,p as default};
